//! Typed identifiers.
//!
//! All identifiers are UUIDv7 values generated by the application layer. Newtypes
//! prevent accidental mixing of identifier kinds at compile time.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

macro_rules! id_type {
    ($name:ident, $label:literal) => {
        #[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
        #[serde(transparent)]
        pub struct $name(Uuid);

        impl $name {
            /// Generates a new time-ordered identifier.
            ///
            /// Only the application layer should call this during command handling.
            pub fn new() -> Self {
                Self(Uuid::now_v7())
            }

            /// Wraps an existing UUID.
            pub const fn from_uuid(value: Uuid) -> Self {
                Self(value)
            }

            /// Parses a UUID string.
            pub fn parse(value: &str) -> Result<Self, uuid::Error> {
                Ok(Self(Uuid::parse_str(value)?))
            }

            pub const fn as_uuid(&self) -> &Uuid {
                &self.0
            }

            /// First eight hexadecimal characters, used in derived names.
            pub fn short(&self) -> String {
                self.0.simple().to_string()[..8].to_string()
            }
        }

        impl Default for $name {
            fn default() -> Self {
                Self::new()
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}", self.0)
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}({})", $label, self.0)
            }
        }

        impl FromStr for $name {
            type Err = uuid::Error;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Self::parse(s)
            }
        }
    };
}

id_type!(ProjectId, "ProjectId");
id_type!(ScenarioId, "ScenarioId");
id_type!(RunId, "RunId");
id_type!(SourceSnapshotId, "SourceSnapshotId");
id_type!(BuildId, "BuildId");
id_type!(ImageId, "ImageId");
id_type!(ContainerId, "ContainerId");
id_type!(DeploymentId, "DeploymentId");
id_type!(EventId, "EventId");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips_as_transparent_string() {
        let id = ProjectId::new();
        let json = serde_json::to_string(&id).unwrap();
        assert_eq!(json, format!("\"{id}\""));
        let back: ProjectId = serde_json::from_str(&json).unwrap();
        assert_eq!(id, back);
    }

    #[test]
    fn short_is_eight_lowercase_hex_characters() {
        let short = RunId::new().short();
        assert_eq!(short.len(), 8);
        assert!(short
            .chars()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
    }

    #[test]
    fn distinct_types_are_not_interchangeable() {
        let id = ProjectId::new();
        let text = id.to_string();
        assert!(RunId::parse(&text).is_ok());
    }
}
